using UnityEngine; [RequireComponent(typeof(CharacterController))] public class IdeaSpacePlayerController : MonoBehaviour { public Transform playerCamera; public float moveSpeed = 4f; public float mouseSensitivity = 2f; public float gravity = -20f; private CharacterController controller; private float cameraPitch = 0f; private float verticalVelocity = 0f; void Start() { controller = GetComponent<CharacterController>(); if (playerCamera == null && Camera.main != null) { playerCamera = Camera.main.transform; } LockCursor(); } void Update() { HandleMouseLook(); HandleMovement(); if (Input.GetKeyDown(KeyCode.Escape)) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; } if (Cursor.lockState == CursorLockMode.None && Input.GetMouseButtonDown(0)) { LockCursor(); } } void HandleMouseLook() { if (Cursor.lockState != CursorLockMode.Locked) { return; } float mouseX = Input.GetAxis("Mouse X") * mouseSensitivity; float mouseY = Input.GetAxis("Mouse Y") * mouseSensitivity; transform.Rotate(0f, mouseX, 0f); cameraPitch -= mouseY; cameraPitch = Mathf.Clamp(cameraPitch, -80f, 80f); playerCamera.localRotation = Quaternion.Euler(cameraPitch, 0f, 0f); } void HandleMovement() { float horizontal = Input.GetAxisRaw("Horizontal"); float vertical = Input.GetAxisRaw("Vertical"); Vector3 move = transform.right * horizontal + transform.forward * vertical; if (move.sqrMagnitude > 1f) { move.Normalize(); } if (controller.isGrounded && verticalVelocity < 0f) { verticalVelocity = -2f; } verticalVelocity += gravity * Time.deltaTime; Vector3 velocity = move * moveSpeed; velocity.y = verticalVelocity; controller.Move(velocity * Time.deltaTime); } void LockCursor() { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; } }